package com.bankpli.javabank.swift;import java.math.BigDecimal;import java.text.*;import java.util.Locale;import org.springframework.stereotype.Service;
@Service public class CurrencyFormatter {public String format(BigDecimal amount,String currency,Locale locale){NumberFormat f=NumberFormat.getCurrencyInstance(locale);try{f.setCurrency(java.util.Currency.getInstance(currency));}catch(IllegalArgumentException e){throw new IllegalArgumentException("Unsupported currency");}return f.format(amount);}public String picture(BigDecimal amount){return new DecimalFormat("***,**0.00;***,**0.00DB").format(amount);}}
